example.code:
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = "eu-west-3"
}

resource "aws_s3_bucket" "reports" {
  bucket = "acme-reports-dev"
  tags   = { team = "data", env = "dev" }
}

variable "env" {
  type        = string
  description = "dev, staging or prod"
}

locals {
  name = "acme-reports-${var.env}"
}

resource "aws_s3_bucket" "reports" {
  bucket = local.name
}

output "bucket_arn" {
  value = aws_s3_bucket.reports.arn
}

terraform {
  backend "s3" {
    bucket       = "acme-terraform-state"
    key          = "reports/dev.tfstate"
    region       = "eu-west-3"
    encrypt      = true
    use_lockfile = true
  }
}

module "reports_dev" {
  source = "./modules/bucket"
  env    = "dev"
}

module "reports_prod" {
  source     = "./modules/bucket"
  env        = "prod"
  versioning = true
}

variable "env" {
  type        = string
  description = "Deployment environment"
  validation {
    condition     = contains(["dev", "staging", "prod"], var.env)
    error_message = "env must be dev, staging or prod."
  }
}

variable "bucket" {
  type = object({
    name       = string
    versioning = optional(bool, false)
    tags       = optional(map(string), {})
  })
}

locals {
  tags = merge({ env = var.env, managed_by = "terraform" }, var.bucket.tags)
}

output "bucket_name" {
  value = aws_s3_bucket.this.bucket
}

variable "buckets" {
  type = map(object({ versioning = bool }))
  default = {
    raw     = { versioning = true }
    curated = { versioning = true }
    tmp     = { versioning = false }
  }
}

resource "aws_s3_bucket" "data" {
  for_each = var.buckets
  bucket   = "acme-${each.key}-${var.env}"
}

resource "aws_security_group" "api" {
  name   = "api-${var.env}"
  vpc_id = var.vpc_id

  dynamic "ingress" {
    for_each = var.allowed_ports
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = [var.vpc_cidr]
    }
  }
}

# Adopt a bucket that was created by hand
import {
  to = aws_s3_bucket.legacy_exports
  id = "acme-legacy-exports"
}

# The block was renamed: keep the same database
moved {
  from = aws_db_instance.main
  to   = module.database.aws_db_instance.this
}

# Stop managing this queue, but do not delete it
removed {
  from = aws_sqs_queue.old_jobs
  lifecycle {
    destroy = false
  }
}

