variable "instance_type" {
  type    = string
  default = "t3.micro"
}

output "web_ip" {
  value = aws_instance.web.public_ip
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
  validation {
    condition     = startswith(var.instance_type, "t3.") || startswith(var.instance_type, "m6i.")
    error_message = "instance_type must be a t3 or m6i size."
  }
}

variable "users" {
  type    = list(string)
  default = ["alice", "bob", "chloe"]
}

resource "aws_iam_user" "team" {
  for_each = toset(var.users)
  name     = each.value
}
